<!doctype html><html><head><meta charset="utf-8"><title>Progress Report · {{ $student['student_name'] }}</title><style>body{margin:0;background:#eef2f6;font-family:Arial;color:#07172d}.sheet{width:850px;max-width:94%;margin:25px auto;padding:38px;background:#fff}.head{display:flex;justify-content:space-between;border-bottom:3px solid #1769ff;padding-bottom:18px}.brand{display:flex;gap:15px;align-items:center}.brand img{width:74px}.brand h1,.brand p{margin:4px 0}.title{text-align:right}.title h2{color:#1769ff}.student{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.student span{padding:12px;background:#f4f7fa;font-size:11px}.student b{display:block;margin-top:5px}.overall{text-align:center;padding:24px;border-radius:14px;background:#eaf1ff}.overall strong{display:block;color:#1769ff;font-size:48px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.metrics div{padding:17px;border:1px solid #dce4ea;border-radius:10px;text-align:center}.metrics strong,.metrics small{display:block}.metrics strong{font-size:24px;margin-bottom:5px}.details{width:100%;border-collapse:collapse;margin-top:18px}.details td{padding:11px;border-bottom:1px solid #dce4ea}.sign{display:flex;justify-content:space-between;margin-top:55px;padding-top:14px;border-top:1px dashed #aab7c2}.actions{text-align:center;margin:20px}.actions button{padding:11px 18px;border:0;border-radius:8px;background:#1769ff;color:#fff;font-weight:bold}@media print{body{background:#fff}.sheet{margin:0;max-width:none;width:auto}.actions{display:none}}@media(max-width:650px){.student,.metrics{grid-template-columns:1fr 1fr}.head{flex-direction:column}.title{text-align:left}}</style></head><body><div class="actions"><button onclick="window.print()">Print Progress Report</button></div><main class="sheet">
<header class="head"><div class="brand"><img src="{{ asset('images/mci-logo.webp') }}" alt="MCI"><div><h1>{{ $settings['site_name'] ?? 'Micro Computer Institute' }}</h1><p>Bihar Sharif, Nalanda</p></div></div><div class="title"><small>STUDENT PERFORMANCE</small><h2>PROGRESS REPORT</h2><p>{{ now()->format('d M Y') }}</p></div></header>
<section class="student"><span>Student Name<b>{{ $student['student_name'] }}</b></span><span>Application No.<b>{{ $student['application_no'] }}</b></span><span>Roll No.<b>{{ $student['roll_no'] ?? 'Not assigned' }}</b></span><span>Course<b>{{ $student['course_code'] }} — {{ $course?->title }}</b></span><span>Batch<b>{{ $student['batch_name'] ?? $student['preferred_time'] ?? 'Not assigned' }}</b></span><span>Phone<b>{{ $student['phone'] }}</b></span></section>
<section class="overall"><small>OVERALL ACADEMIC PROGRESS</small><strong>{{ number_format($progress['overall'],1) }}%</strong><b>{{ $progress['grade'] }}</b></section>
<section class="metrics"><div><strong>{{ $progress['attendance_rate']===null?'—':$progress['attendance_rate'].'%' }}</strong><small>Attendance ({{ $progress['attendance_total'] }} days)</small></div><div><strong>{{ $progress['assignment_average']===null?'—':$progress['assignment_average'].'%' }}</strong><small>Assignments ({{ $progress['assignment_count'] }})</small></div><div><strong>{{ $progress['practice_average']===null?'—':$progress['practice_average'].'%' }}</strong><small>Practice Tests ({{ $progress['practice_count'] }})</small></div><div><strong>{{ $progress['exam_average']===null?'—':$progress['exam_average'].'%' }}</strong><small>Exams ({{ $progress['exam_count'] }})</small></div></section>
<table class="details"><tr><td>Course Fee</td><td>₹{{ number_format($progress['course_fee'],2) }}</td></tr><tr><td>Paid Amount</td><td>₹{{ number_format($progress['paid_amount'],2) }}</td></tr><tr><td>Balance Due</td><td><b>₹{{ number_format($progress['balance_amount'],2) }}</b></td></tr><tr><td>Fee Completion</td><td>{{ $progress['fee_percentage'] }}%</td></tr></table>
<footer class="sign"><span>Student / Guardian Signature</span><span>Authorized Signatory</span></footer></main></body></html>